tool_input.command:
mkdir -p "$TMPDIR/rp_script" && cat > "$TMPDIR/rp_script/compare.py" <<'EOF'
import ast, sys

MASK = "graph" + "-access"          # never print the vendor rule's name whole

def mask(s):
    return "<CODE-SEARCH-RULE>" if isinstance(s, str) and MASK in s else s

def load(path):
    tree = ast.parse(open(path, encoding="utf-8").read(), path)
    env = {}
    for node in tree.body:
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
            try:
                env[node.targets[0].id] = eval(compile(ast.Expression(node.value), path, "eval"), {"__builtins__": {}}, dict(env))
            except Exception:
                pass
    return tree, env

old_tree, old_env = load(sys.argv[1])
new_tree, new_env = load(sys.argv[2])

for name in ("DEFAULT_RULES", "NO_CASE", "PROJECT_RULES"):
    o, n = old_env.get(name), new_env.get(name)
    print(f"{name}: old type={type(o).__name__} len={len(o) if o is not None else None}; "
          f"new type={type(n).__name__} len={len(n) if n is not None else None}; equal={o == n}")

o, n = old_env["DEFAULT_RULES"], new_env["DEFAULT_RULES"]
diffpos = [i for i, (a, b) in enumerate(zip(o, n)) if a != b]
print("DEFAULT_RULES positions differing:", diffpos)
print("DEFAULT_RULES duplicates old/new:", len(o) - len(set(o)), len(n) - len(set(n)))
idx = [i for i, r in enumerate(n) if MASK in r]
print("code-search rule position (new):", idx, "in old at:", [i for i, r in enumerate(o) if MASK in r])
print("new-only constants:", sorted(set(new_env) - set(old_env)), "| old-only:", sorted(set(old_env) - set(new_env)))
for k in sorted(set(old_env) & set(new_env)):
    if old_env[k] != new_env[k]:
        print("CHANGED constant:", k)

# RULE_IDS: what it maps
ri = new_env.get("RULE_IDS", {})
print("RULE_IDS:", {mask(k): mask(v) for k, v in ri.items()}, "keys in DEFAULT_RULES:", [k in n for k in ri])

# Top-level node comparison
def key(node):
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        return ("def", node.name)
    if isinstance(node, ast.Assign):
        return ("assign", tuple(ast.dump(t) for t in node.targets))
    return ("other", ast.dump(node)[:80])

def strip(node):
    return ast.dump(node, include_attributes=False)

old_nodes = {key(nd): nd for nd in old_tree.body}
new_nodes = {key(nd): nd for nd in new_tree.body}
print("top-level nodes old/new:", len(old_tree.body), len(new_tree.body))
print("order of common keys identical:", [k for k in (key(x) for x in old_tree.body) if k in new_nodes] == [k for k in (key(x) for x in new_tree.body) if k in old_nodes])
for k in old_nodes:
    if k not in new_nodes:
        print("REMOVED:", k[0], mask(k[1]) if isinstance(k[1], str) else "...")
for k in new_nodes:
    if k not in old_nodes:
        print("ADDED:", k[0], k[1] if isinstance(k[1], str) else [mask(s) for s in k[1]])
funcs = 0
for k, nd in old_nodes.items():
    if k in new_nodes and strip(nd) != strip(new_nodes[k]):
        print("DIFFERS:", k[0], k[1] if isinstance(k[1], str) else "assign")
        if isinstance(nd, ast.FunctionDef):
            ob, nb = nd.body, new_nodes[k].body
            print("   body identical:", [strip(x) for x in ob] == [strip(x) for x in nb])
            print("   args identical:", strip(nd.args) == strip(new_nodes[k].args))
            print("   returns identical:", strip(nd.returns) if nd.returns else None, "==", strip(new_nodes[k].returns) if new_nodes[k].returns else None)
            print("   decorators old:", len(nd.decorator_list), "new:", len(new_nodes[k].decorator_list))
            for i, (a, b) in enumerate(zip(nd.decorator_list, new_nodes[k].decorator_list)):
                print(f"   decorator {i} identical:", strip(a) == strip(b))
                if strip(a) != strip(b):
                    print("     old:", ast.unparse(a))
                    print("     new:", ast.unparse(b))
    if isinstance(nd, ast.FunctionDef) and nd.name.startswith("test_"):
        funcs += 1
print("test functions (old):", funcs, "(new):", sum(1 for k, v in new_nodes.items() if isinstance(v, ast.FunctionDef) and v.name.startswith("test_")))
EOF
python3 -I "$TMPDIR/rp_script/compare.py" "$TMPDIR/rp/old.py" "$TMPDIR/rp/new.py"
